// LiTTree P0 Error Handler v3.4 — Normalize Error (runOnceForAllItems)
// Produces ONE normalized alert record. No external calls; never requires.
// CONFIG: re-alert interval. The same (workflow, error) alerts at most once
// per UTC bucket of RE_ALERT_MINUTES. Change with care: shorter = noisier.
//
// v3.4: field mappings corrected against the ACTUAL n8n Error Trigger schema
// (n8n docs): {execution: {id, url, error: {message, stack}, lastNodeExecuted,
// mode}, workflow: {id, name}}. Also handles the trigger-node-error variant
// ({trigger: {error, mode}, workflow: {id, name}}), which carries less info.
var RE_ALERT_MINUTES = 60;

function sigOf(msg, nodeName, wfName) {
  var parts = [msg || '', nodeName || '', wfName || ''];
  return parts.filter(Boolean).join(' | ').slice(0, 500) || 'empty-error';
}
function hash53(str, seed) {
  var h1 = 0xdeadbeef ^ seed, h2 = 0x41c6ce57 ^ seed;
  for (var i = 0, ch; i < str.length; i++) {
    ch = str.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(36);
}
// Bucketed re-alert key: identical failures in the same UTC bucket share a
// key (suppressed); the next bucket yields a new key (re-alert allowed).
function alertKeyFor(workflowId, signature, nowMs) {
  var bucket = Math.floor(nowMs / (RE_ALERT_MINUTES * 60 * 1000));
  return hash53(workflowId + '|' + signature + '|' + bucket, 0);
}

var items = $input.all();
var trigger = items.length ? items[0].json : {};
var ex = trigger.execution || {};
var wf = trigger.workflow || {};
// Error object: execution.error normally; trigger.error when the failed
// workflow's own trigger node errored (different schema, less info).
var errObj = ex.error || ((trigger.trigger || {}).error) || {};
var errMsg = errObj.message || '';
if (typeof errMsg !== 'string') errMsg = String(errMsg);
var workflowId = String(wf.id || wf.name || 'unknown');
var signature = sigOf(errMsg, ex.lastNodeExecuted, wf.name || wf.id);

return [{
  json: {
    alert_key: alertKeyFor(workflowId, signature, Date.now()),
    workflow_id: workflowId,
    workflow_name: String(wf.name || workflowId),
    error_message: (errMsg || signature).slice(0, 2000),
    error_signature: signature,
    failed_node: String(ex.lastNodeExecuted || ''),
    execution_id: String(ex.id || ''),
    execution_url: String(ex.url || ''),
    occurred_at: new Date().toISOString(),
    realert_minutes: RE_ALERT_MINUTES,
  }
}];

// LiTTree P0 Error Handler v3.1 — Classify Claim Error (runOnceForAllItems)
// Reads the failed Claim Alert Slot insert (paired item) and decides:
//   - PK conflict (23505 / duplicate key) => duplicate, stop.
//   - anything else (DB down, RLS, timeout, response lost) => fail OPEN:
//     send the alert anyway. A duplicate alert is acceptable; a lost P0
//     alert is not.
var items = $input.all();
var errJson = items.length ? items[0].json : {};
var msg = JSON.stringify(errJson).toLowerCase();
var dup = /duplicate key|23505|unique constraint|conflict/i.test(msg)
       || /already exists/i.test(msg);
return [{
  json: {
    alert_key: $('Normalize Error').first().json.alert_key,
    workflow_id: $('Normalize Error').first().json.workflow_id,
    error_message: $('Normalize Error').first().json.error_message,
    error_signature: $('Normalize Error').first().json.error_signature,
    failed_node: $('Normalize Error').first().json.failed_node,
    execution_id: $('Normalize Error').first().json.execution_id,
    execution_url: $('Normalize Error').first().json.execution_url,
    occurred_at: $('Normalize Error').first().json.occurred_at,
    is_duplicate: !!dup,
    dedup_degraded: !dup,   // true when we could not reach the claims table
    claim_error: String(errJson.message || errJson.error || 'unknown').slice(0, 500),
  }
}];

