// LiTTree P0 Error Handler v3.1 — Confirm Fallback (runOnceForAllItems)
// The Gmail v2 send operation returns the Gmail message resource, which
// always carries an `id` on success. Empty/missing id => NOT confirmed.
var items = $input.all();
var j = items.length ? items[0].json : {};
var norm = $('Normalize Error').first().json;
var id = j && j.id;
return [{
  json: {
    alert_key: norm.alert_key,
    workflow_id: norm.workflow_id,
    error_message: norm.error_message,
    error_signature: norm.error_signature,
    failed_node: norm.failed_node,
    execution_id: norm.execution_id,
    execution_url: norm.execution_url,
    occurred_at: norm.occurred_at,
    fallback_confirmed: typeof id === 'string' && id.length > 0,
    channel: 'email',
  }
}];

// LiTTree P0 Error Handler v3.4 — Resolve Delivery Record (runOnceForAllItems)
// Runs on BOTH outputs of Backfill Claim (shared by the Discord and Email
// delivery paths). Decides whether the delivery can be RECORDED:
//   - backfill ok, or 23505/conflict (claim row already exists) => recordable
//   - backfill failed otherwise (Supabase unavailable)           => NOT recordable
// A non-recordable delivery ends at the explicit "Delivered — Unrecorded"
// terminal. A successfully delivered alert is NEVER reported as a failure.
//
// v3.4: channel attribution fixed — prefer the Confirm node whose delivery
// actually CONFIRMED. v3.3 checked Confirm Delivery first, which always ran,
// misrecording Gmail deliveries as Discord.
function confirmJson() {
  var fb = null, dc = null;
  try { fb = $('Confirm Fallback').first().json; } catch (e) {}
  try { dc = $('Confirm Delivery').first().json; } catch (e) {}
  if (fb && fb.fallback_confirmed && fb.alert_key) return fb;
  if (dc && dc.delivery_confirmed && dc.alert_key) return dc;
  if (fb && fb.alert_key) return fb;
  if (dc && dc.alert_key) return dc;
  return {};
}
var items = $input.all();
var raw = items.length ? items[0].json : {};
var src = confirmJson();
var isErr = !!(raw && raw.error);
var msg = isErr ? JSON.stringify(raw).toLowerCase() : '';
var conflict = /duplicate key|23505|unique constraint|conflict/i.test(msg)
            || /already exists/i.test(msg);
var recordable = !isErr || conflict;
return [{
  json: {
    alert_key: src.alert_key || raw.alert_key || '',
    channel: src.channel || 'unknown',
    error_signature: src.error_signature || '',
    recordable: recordable,
    backfill_error: (isErr && !conflict)
      ? String((raw.error && raw.error.message) || raw.message || 'unknown').slice(0, 500)
      : '',
  }
}];

// LiTTree P0 Error Handler v3.1 — Fail Loudly (runOnceForAllItems)
// Reached ONLY when Discord failed AND the Gmail fallback failed.
// Throwing marks the error-workflow execution FAILED (visible, paging-worthy)
// instead of silently swallowing a P0 alert.
var norm = $('Normalize Error').first().json;
throw new Error(
  '[LiTT-P0] ALERT DELIVERY FAILED for key=' + norm.alert_key +
  ' workflow=' + norm.workflow_id +
  ' error=' + String(norm.error_message).slice(0, 200)
);

// LiTTree P0 Error Handler v3.3 — Capture Record Error (runOnceForAllItems)
// "Delivered — Recorded" threw AFTER a confirmed delivery (e.g. transient DB
// failure on the deliveries insert). The alert WAS delivered; only the
// outcome record is missing. Preserve the DB error details + delivery
// context for diagnostics, then terminate at Delivered — Unrecorded.
// Explicit success outcome — never a misleading execution failure, and the
// database error is never silently discarded.
var errItem = ($input.first() || {}).json || {};
var rec = {};
try { rec = ($('Resolve Delivery Record').first() || {}).json || {}; } catch (e) {}
var errObj = errItem.error || {};
var detail = errObj.message || errItem.error || errItem.message || 'unknown';
return [{
  json: {
    alert_key: rec.alert_key || '',
    channel: rec.channel || 'unknown',
    error_signature: rec.error_signature || '',
    outcome: 'delivered-unrecorded',
    record_error: String(detail).slice(0, 1000),
    recorded_at: new Date().toISOString(),
  }
}];
